#!/usr/bin/env node
/**
 * Writes scripts/test_seed.sql and scripts/test_seed_cleanup.sql from
 * tests/fixtures/exam-fixture.mjs. These are run BY A HUMAN in the Supabase SQL
 * editor — the app and its tests never write to the live database.
 *   node tests/fixtures/make-test-seed.mjs
 */
import { writeFileSync } from "node:fs";
import { EXAMS, LESSON_ID, QUESTIONS, SEED, examQuestionId, hasManual, questionId, testId, totalMarks, versionId } from "./exam-fixture.mjs";

const j = (v) => `$j$${JSON.stringify(v)}$j$::jsonb`;
const t = (s) => (s === null || s === undefined ? "null" : `$t$${s}$t$`);
const ids = (list) => list.map((x) => `'${x}'`).join(", ");

const EXAMPLE_ID = testId("example");
const RES_LINK = testId("resource:link");
const RES_VIDEO = testId("resource:video");
const usedQuestions = [...new Set(EXAMS.flatMap((e) => e.questions))];
const examIds = EXAMS.map((e) => e.id);
const contentIds = [LESSON_ID, EXAMPLE_ID, RES_LINK, RES_VIDEO, ...usedQuestions.map(versionId)];

const header = (what) => `-- =============================================================================
-- ${what}
-- GENERATED by tests/fixtures/make-test-seed.mjs — do not edit by hand.
-- TEST DATA ONLY. Every row uses a fixed id derived from md5('haqq:test:…') and
-- every title is marked «[تجريبي]». Run in the Supabase SQL editor.
-- =============================================================================
`;

const lessonBody = "[تجريبي] هذا درس لاختبار عرض المنصة.\\n\\nمثال: [[quran:2:121:1-6]]";

let seed = header("Test seed: one published lesson + 3 published exams (reversible: scripts/test_seed_cleanup.sql)") + `
begin;

do $$ begin
  if not exists (select 1 from public.chapters where id = '${SEED.chapterL1C2}') then
    raise exception 'Run supabase/seed/0001_minhaj_al_darisin.sql first (chapter l1-c2 is missing).';
  end if;
  if exists (select 1 from public.exams where id in (${ids(examIds)})) then
    raise exception 'Test seed already applied. Run scripts/test_seed_cleanup.sql first to re-apply.';
  end if;
end $$;

-- Same mechanism transition_content()/publish_exam() use internally; transaction-local only.
select set_config('app.content_transition', 'on', true);
select set_config('app.exam_transition', 'on', true);

-- Lesson (published, reviewed) in المستوى الأول › الباب الثاني
insert into public.lessons (id, chapter_id, code, sort_order, title, description, objectives, body_md, definitions, rules, tables,
                            youtube_ids, origin, source_edition_id, source_page_start, source_page_end, status, scientifically_verified)
values ('${LESSON_ID}', '${SEED.chapterL1C2}', 'zz-test-lesson', 99, ${t("[تجريبي] درس تجريبي لأحكام النون")}, ${t("[تجريبي] للتحقق من عرض الدروس.")},
        array[${t("أن يتحقق الفريق من عرض الدرس")}], E'${lessonBody}',
        ${j([{ term: "النون الساكنة", definition: "[تجريبي] تعريف تجريبي.", source_page: 49 }])},
        ${j([{ title: "الإظهار الحلقي", body: "[تجريبي] قاعدة تجريبية.", source_page: 51 }])},
        ${j([{ caption: "[تجريبي] جدول", columns: ["الحرف", "المخرج"], rows: [["ء", "أقصى الحلق"]], source_page: 52 }])},
        '{}', 'supplementary_explanation', '${SEED.edition}', 49, 65, 'published', true);

-- Quranic example stored by REFERENCE only (الفاتحة ٢–٤); text comes from the verified Tanzil bundle.
insert into public.quranic_examples (id, riwayah_id, surah, ayah_start, ayah_end, note, origin, source_edition_id, source_page_start, status, scientifically_verified)
values ('${EXAMPLE_ID}', '${SEED.riwayah}', 1, 2, 4, ${t("[تجريبي]")}, 'supplementary_explanation', '${SEED.edition}', 52, 'published', true);
insert into public.lesson_examples (lesson_id, example_id, sort_order, rule_note) values ('${LESSON_ID}', '${EXAMPLE_ID}', 1, ${t("[تجريبي] مثال")});

insert into public.resources (id, kind, title, provider, external_url, youtube_id, is_downloadable, origin, status, scientifically_verified) values
  ('${RES_LINK}', 'link', ${t("[تجريبي] رابط مشروع تنزيل")}, 'external', 'https://tanzil.net', null, false, 'independent_material', 'published', true),
  ('${RES_VIDEO}', 'video', ${t("[تجريبي] مقطع مرئي")}, 'youtube', null, 'dQw4w9WgXcQ', false, 'independent_material', 'published', true);
insert into public.lesson_resources (lesson_id, resource_id, sort_order) values ('${LESSON_ID}', '${RES_LINK}', 1), ('${LESSON_ID}', '${RES_VIDEO}', 2);

-- Question bank: published, reviewed versions with keys (keys stay in question_keys)
`;
for (const q of usedQuestions) {
  const d = QUESTIONS[q];
  seed += `insert into public.questions (id, edition_id, level_id, chapter_id, lesson_id, difficulty, tags) values ('${questionId(q)}', '${SEED.edition}', '${SEED.level1}', '${SEED.chapterL1C2}', '${LESSON_ID}', 2, '{test}');
insert into public.question_versions (id, question_id, version_no, prompt, origin, status, scientifically_verified) values ('${versionId(q)}', '${questionId(q)}', 1, ${j(d.prompt)}, 'independent_material', 'published', true);
insert into public.question_keys (question_version_id, key, model_answer, explanation) values ('${versionId(q)}', ${j(d.key)}, ${j(d.model_answer ?? {})}, ${t(d.explanation ?? null)});
update public.questions set current_version_id = '${versionId(q)}' where id = '${questionId(q)}';
`;
}
seed += `\n-- Exams: created as drafts, papers attached, then published (as publish_exam() does)\n`;
for (const e of EXAMS) {
  seed += `insert into public.exams (id, slug, title, description, edition_id, level_id, chapter_id, lesson_id, kind, is_level_final, requires_account,
                          pass_percent, time_limit_minutes, result_release, model_answer_visibility, status)
values ('${e.id}', '${e.slug}', ${t(e.title)}, ${t(e.description)}, '${e.edition_id}', '${e.level_id}', ${e.chapter_id ? `'${e.chapter_id}'` : "null"}, ${e.lesson ? `'${LESSON_ID}'` : "null"},
        '${e.kind}', ${e.is_level_final}, ${e.requires_account}, ${e.pass_percent}, ${e.time_limit_minutes ?? "null"}, '${e.result_release}', '${e.model_answer_visibility}', 'draft');
`;
  e.questions.forEach((q, i) => {
    seed += `insert into public.exam_questions (id, exam_id, question_version_id, sort_order, is_required) values ('${examQuestionId(e.key, q)}', '${e.id}', '${versionId(q)}', ${i + 1}, true);\n`;
  });
  seed += `update public.exams set status = 'published', total_marks = ${totalMarks(e)}, has_manual_parts = ${hasManual(e)} where id = '${e.id}';\n\n`;
}
seed += `commit;

-- Check: anonymous visitors should now see 1 lesson and 3 exams
--   node --env-file=.env.local scripts/check-live-access.mjs
-- Exams:
${EXAMS.map((e) => `--   /exams/${e.id}/  (${e.slug})`).join("\n")}
-- Lesson: /levels/l1/l1-c2/zz-test-lesson/  (after a site rebuild)
`;

const cleanup = header("Cleanup: removes EVERYTHING created by scripts/test_seed.sql (incl. attempts on the test exams)") + `
begin;
select set_config('app.content_transition', 'on', true);
select set_config('app.exam_transition', 'on', true);

delete from public.notifications where link in (select '/attempts/' || id from public.exam_attempts where exam_id in (${ids(examIds)}));
delete from public.exam_attempts where exam_id in (${ids(examIds)});       -- cascades attempt_answers
update public.exams set status = 'draft' where id in (${ids(examIds)});      -- papers are frozen while published
delete from public.exam_questions where exam_id in (${ids(examIds)});
delete from public.exams where id in (${ids(examIds)});

update public.questions set current_version_id = null where id in (${ids(usedQuestions.map(questionId))});
delete from public.question_keys where question_version_id in (${ids(usedQuestions.map(versionId))});
delete from public.question_versions where question_id in (${ids(usedQuestions.map(questionId))});
delete from public.questions where id in (${ids(usedQuestions.map(questionId))});

delete from public.lessons where id = '${LESSON_ID}';                        -- cascades links, progress, bookmarks
delete from public.quranic_examples where id = '${EXAMPLE_ID}';
delete from public.resources where id in (${ids([RES_LINK, RES_VIDEO])});

delete from public.review_comments where entity_id in (${ids(contentIds)});
delete from public.review_assignments where entity_id in (${ids(contentIds)});
delete from public.review_events where entity_id in (${ids(contentIds)});
commit;
-- audit_log rows are append-only by design and are left in place.
`;

writeFileSync(new URL("../../scripts/test_seed.sql", import.meta.url), seed);
writeFileSync(new URL("../../scripts/test_seed_cleanup.sql", import.meta.url), cleanup);
console.log("wrote scripts/test_seed.sql and scripts/test_seed_cleanup.sql");
